          out.push(movingChr(450-d,y,left[k],sc[k],-1,left[k]===COLORS.pink?COLORS.blue:COLORS.pink,true),movingChr(450+d,y,right[k],sc[k],1,right[k]===COLORS.pink?COLORS.blue:COLORS.pink,true));
