            if(e<.38) out.push(replicatingChromatin(cx-20,235,sets[j][0],.48,p+j*.1,1,.82),replicatingChromatin(cx+20,345,sets[j][1],.37,p+j*.16,1,.82));
            else out.push(xChr(cx-20,235,sets[j][0],.82,-8,sets[j][0]===COLORS.pink?COLORS.blue:COLORS.pink),xChr(cx+20,345,sets[j][1],.62,8,sets[j][1]===COLORS.pink?COLORS.blue:COLORS.pink));
